import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.Ke88N3OB.js";var c=JSON.parse(`{"title":"Waypoints","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/waypoints/docs/index.md"},"headers":[],"relativePath":"packages/waypoints/docs/index.md","filePath":"packages/waypoints/docs/index.md","lastUpdated":1792508949000}`),l={name:`packages/waypoints/docs/index.md`},u={id:`waypoints`,tabindex:`-1`,class:`component-page-title`},d={class:`component-page-title__version`,href:`https://github.com/filiphsps/pumpkin-plugins/releases/tag/waypoints-v0.1.0`,"aria-label":`Release v0.1.0`};function f(i,c,l,f,p,m){let h=s(`Badge`);return e(),o(`div`,null,[n(`h1`,u,[c[0]||=n(`img`,{class:`component-page-title__icon`,src:`/pumpkin-plugins/packages/waypoints/icon.svg`,alt:``,"aria-hidden":`true`,width:`48`,height:`48`},null,-1),c[1]||=n(`span`,{class:`component-page-title__text`},[t(`Waypoints `),n(`a`,{class:`header-anchor`,href:`#waypoints`,"aria-label":`Permalink to “Waypoints”`},`​`)],-1),n(`a`,d,[a(h,{type:`info`,text:`v0.1.0`})])]),c[2]||=r(`<p>Waypoints stores shared named locations on the server. Each waypoint can have a display label, description, color, item icon, and optional HUD visibility range. Waypoints are restricted by default; operators can make them public or grant access to specific players, permission nodes, or permission-marker groups. Players can find and teleport to enabled waypoints they can access. Records have no creator ownership.</p><p>Optional PumpkinPIE placeholders expose live, access-filtered waypoint data. See the <a href="./placeholders">placeholder guide</a> for the complete contract.</p><p>Install <code>waypoints.wasm</code> in the Pumpkin server&#39;s <code>plugins/</code> directory and restart. The plugin has no config file. It stores versioned records in <code>plugins/data/Waypoints/waypoints.json</code>. A v1 migration copies <code>locatorBar.color</code> to the waypoint&#39;s v2 <code>color</code>. The Java adapter&#39;s <code>locatorBar.enabled</code> value did not control the whole waypoint, so it does not set v2 <code>enabled</code>, which defaults to <code>true</code>. V2 has no matching style or platform-adapter fields for Java <code>javaStyleId</code> or Bedrock <code>bedrockTexture</code>. The byte-identical <code>waypoints.v1.json</code> backup preserves all original v1 settings.</p><h2 id="create-and-use-waypoints" tabindex="-1">Create and use waypoints <a class="header-anchor" href="#create-and-use-waypoints" aria-label="Permalink to “Create and use waypoints”">​</a></h2><p>Admins can create a waypoint at their exact position with <code>/wp create &quot;Home Base&quot;</code>, or provide absolute coordinates with <code>/wp create &quot;Home Base&quot; 120.5 64 -30</code>. X and Z must be within 30,000,000 blocks of the origin and Y within 20,000,000, the limits of vanilla <code>/tp</code>. Names are unique across all dimensions. Use <code>/wp list</code> to see enabled waypoints you can access, <code>/wp info &lt;name&gt;</code> for details, and <code>/wp tp &lt;name&gt;</code> to teleport yourself. Admins can use <code>/wp tp &lt;name&gt; @a</code> to teleport a player selector.</p><p>Creating, editing, enabling, disabling, granting, and deleting waypoints needs the <code>Waypoints:command.admin</code> permission. It defaults to operator level 3, and a permissions plugin can grant it to other players. Server operators can see and teleport to every enabled waypoint, regardless of its access rules.</p><p>The server console and RCON hold every permission, so they can run the admin commands too. The exceptions are <code>/wp create</code> and <code>/wp relocate</code>, which use the sender&#39;s position or world and need a player. Over RCON, <code>/wp set icon</code> fails because Pumpkin doesn&#39;t pass the item to the plugin.</p><p>Player grants resolve online names and store UUIDs. To revoke the grant of an offline player, pass the UUID that <code>/wp access list</code> shows. A group grant checks the permission marker <code>Waypoints:group.&lt;slug&gt;</code>; another permission provider must assign that marker to group members.</p><h2 id="java-waypoint-hud" tabindex="-1">Java waypoint HUD <a class="header-anchor" href="#java-waypoint-hud" aria-label="Permalink to “Java waypoint HUD”">​</a></h2><p>Only Java clients whose reported version exactly matches the gate below receive HUD updates:</p><p>Required Java version: <code>v-26-3</code>.</p><p>Players see each enabled waypoint they can access in the same dimension and within the optional visibility range. Private display packets keep restricted names and personalized distances off other clients. Names reveal after a settled look and stay visible near the destination; distant peripheral markers show just their distance and icon. Labels use the waypoint color, a shadow, and a subtle backdrop independent of world lighting. Iconless waypoints use a colored diamond.</p><p>The HUD uses client-only TextDisplay entities along each waypoint&#39;s world direction. A smooth depth curve approaches a maximum of 24 blocks from the player&#39;s eyes, reducing the apparent movement caused by delayed position samples. Labels face the viewer and render through terrain. Camera rotation does not move or replace them. Between sixteen and three blocks from a waypoint, the projection blends into a world anchor two blocks above its stored Y coordinate. It never passes the destination during the blend; within three blocks it stays at the anchor. The transition works in both directions.</p><p>Perspective sizing uses camera-forward depth to avoid enlarging labels at the screen edges, and keeps their apparent size consistent through the approach at a fixed field of view. Labels are limited to 32 characters on the HUD; <code>/wp info</code> retains the complete text. Distances use meters below one kilometer and tenths of kilometers above it, with hysteresis to prevent rounding flicker. Text, icons, and backdrop fade between two and 0.75 blocks from the destination, leaving the immediate view clear.</p><p>Waypoints stored in the same half-block grid cell get a stable vertical stack, ordered by identifier, without camera-dependent rearrangement. Distinct waypoints along the same bearing may still overlap. Steps and jumps receive strong elevation damping while steep vertical destinations respond faster. Damping eases off near the world anchor. Position and scale updates interpolate over one client tick; unchanged text is not resent for appearance-only updates.</p><p>This approximates a first-person HUD: network latency, client view bobbing, and third-person camera offsets can still affect alignment. The server cannot read client FOV or reliably detect Java item-use state, so spyglass and modded zoom enlarge the labels. Other Java protocol versions do not receive the HUD; the server log notes each such player once per session. This HUD supports Java clients only. Waypoints does not currently render Bedrock HUDs. Icons use vanilla atlas textures; block items use a representative model texture, and custom item IDs require the corresponding <code>item/&lt;path&gt;</code> sprite in the client&#39;s resource pack. The map of block item sprites comes from a Minecraft client JAR; after a Minecraft update, regenerate it with <code>pnpm --filter @pumpkin-plugins/waypoints icons &lt;client.jar&gt;</code>.</p><p>Malformed or unsupported storage is preserved and disables writes. Fix the file before expecting changes to persist.</p>`,17)])}var p=i(l,[[`render`,f]]);export{c as __pageData,p as default};